# The database's own balance check learns the conversion rule: with a declared conversion the
# entry balances in its base currency, each other currency's total converted at the declared
# rate and rounded half up to six places, the same rounding the domain uses.
BALANCED_WITH_CONVERSION = """
CREATE OR REPLACE FUNCTION tally_assert_entry_balanced(entry bigint)
RETURNS void LANGUAGE plpgsql AS $$
DECLARE
  bad record;
  n bigint;
  conv jsonb;
  total numeric;
BEGIN
  SELECT count(*) INTO n FROM journal_lines WHERE entry_id = entry;
  IF n < 2 THEN
    RAISE EXCEPTION 'entry % has % line(s); an entry needs at least two', entry, n
      USING ERRCODE = 'check_violation';
  END IF;
  SELECT conversion INTO conv FROM journal_entries WHERE id = entry;
  IF conv IS NULL THEN
    SELECT currency, sum(amount) AS total INTO bad
      FROM journal_lines WHERE entry_id = entry
      GROUP BY currency HAVING sum(amount) <> 0 LIMIT 1;
    IF FOUND THEN
      RAISE EXCEPTION 'entry % is unbalanced: lines in % sum to %', entry, bad.currency, bad.total
        USING ERRCODE = 'check_violation';
    END IF;
  ELSE
    SELECT sum(CASE WHEN per.currency = conv->>'base' THEN per.total
                    ELSE round(per.total * (conv->'rates'->>per.currency)::numeric, 6) END)
      INTO total
      FROM (SELECT currency, sum(amount) AS total FROM journal_lines WHERE entry_id = entry
            GROUP BY currency HAVING sum(amount) <> 0) per;
    IF total IS NULL OR total <> 0 THEN
      RAISE EXCEPTION 'entry % is unbalanced after conversion to %: % (null means a missing rate)',
        entry, conv->>'base', total USING ERRCODE = 'check_violation';
    END IF;
  END IF;
END $$;
"""

